const gateDetail=CobaltExecutionUI.detail.bind(CobaltExecutionUI);CobaltExecutionUI.detail=async function(id){await gateDetail(id);document.querySelector('.co-execution-page h2')?.insertAdjacentHTML('afterend','<p class="dialog-notice">'+GateUI.t('原版本离场节点保留为出库流程申报，不代表车辆实际通过厂区出口。完成最终出库审批后，由销售在车辆出厂管理中打印出门证并确认实际出厂。既有离场历史保留原始含义和时间。','The legacy departure node is retained as an outbound workflow declaration. It does not establish physical gate exit. After final approval, Sales prints the permit and confirms physical exit in Vehicle Gate Exit. Existing departure history keeps its original meaning and time.')+'</p>');};

